@dataclass
class BulkActionAppealsRequest(DataClassJsonMixin):
    # Action to apply: unban, restore, unblock, mark_reviewed, or reject_appeal
    action_type: str = dc_field(metadata=dc_config(field_name="action_type"))
    # List of appeal UUIDs to process
    appeal_ids: list[str] = dc_field(metadata=dc_config(field_name="appeal_ids"))
    user_id: str | None = dc_field(
        default=None, metadata=dc_config(field_name="user_id")
    )
    # Configuration for mark reviewed action
    mark_reviewed: "MarkReviewedRequestPayload | None" = dc_field(
        default=None, metadata=dc_config(field_name="mark_reviewed")
    )
    # Configuration for rejecting an appeal
    reject_appeal: "RejectAppealRequestPayload | None" = dc_field(
        default=None, metadata=dc_config(field_name="reject_appeal")
    )
    # Configuration for restore action. State-aware: reverses whichever of a delete, a block, or a shadow block currently applies to the content (including both a delete and a block/shadow block at once).
    restore: "RestoreActionRequestPayload | None" = dc_field(
        default=None, metadata=dc_config(field_name="restore")
    )
    # Configuration for unban moderation action
    unban: "UnbanActionRequestPayload | None" = dc_field(
        default=None, metadata=dc_config(field_name="unban")
    )
    # Deprecated: use restore instead — it now also reverses a block or shadow block. Configuration for unblock action.
    unblock: "UnblockActionRequestPayload | None" = dc_field(
        default=None, metadata=dc_config(field_name="unblock")
    )
    # User request object
    user: "UserRequest | None" = dc_field(
        default=None, metadata=dc_config(field_name="user")
    )


